<script setup>
import {ref,computed,onMounted,onBeforeUnmount,defineAsyncComponent} from 'vue';
import { defaultCalibration } from '../spatial.js';
import {Workout,phasesFor} from '../workout.js';import {getProgram, programs} from '../catalog.js';
const FitnessScene=defineAsyncComponent(()=>import('./FitnessScene.vue'));
const calibration=ref({ ...defaultCalibration });
const blocks=ref([{program:'rhythm',sets:2,workSeconds:30,restSeconds:15}]),name=ref('我的组合训练'),description=ref(''),plans=ref([]),editing=ref(null),showArchived=ref(false);
const state=ref('idle'),position=ref({}),summary=ref({workMs:0,restMs:0,hits:0}),message=ref(''),history=ref([]),saving=ref(false),planBusy=ref(false),savedId=ref('');
let workout,timer;const key='vrfitai.workout.v1';
const presets=[{name:'组合入门',blocks:[{program:'rhythm',sets:2,workSeconds:30,restSeconds:15}]},{name:'停留与休息',blocks:[{program:'focus',sets:3,workSeconds:45,restSeconds:15}]},{name:'间歇组合',blocks:[{program:'focus',sets:2,workSeconds:30,restSeconds:15},{program:'flow',sets:2,workSeconds:30,restSeconds:20}]}];
const preview=computed(()=>{try{const p=phasesFor({version:1,blocks:blocks.value});return{seconds:p.reduce((n,x)=>n+x.ms,0)/1000,sets:p.filter(p=>p.type==='work').length}}catch{return null}});
async function api(url,options){const r=await fetch(url,options),v=await r.json();if(!r.ok)throw new Error(v.error||'请求失败');return v}
function refresh(){if(!workout)return;position.value=workout.tick();state.value=workout.state;summary.value=workout.summary();try{localStorage.setItem(key,JSON.stringify({savedAt:Date.now(),snapshot:workout.snapshot()}));}catch{message.value='浏览器无法保存，刷新前请留意训练进度。';}}
function start(){try{workout=new Workout({version:1,blocks:blocks.value.map(x=>({...x}))});workout.planName=name.value.trim().slice(0,60)||'分组训练';workout.start();savedId.value='';message.value='';refresh();}catch{message.value='请检查组数、训练与休息时长，计划总时长不能超过两小时。';}}
function toggle(){if(state.value==='running')workout.pause();else if(state.value==='paused')workout.resume();refresh();}
function hit(){workout?.hit();refresh();}
function pause(){if(workout?.state==='running'){workout.pause();refresh()}}
function stop(){if(!confirm('结束本次训练？将保留已经完成的练习时间，不把未完成的课程段计入。'))return;workout.stop();refresh()}
async function load(){try{[history.value,plans.value]=await Promise.all([api('/api/workouts'),api('/api/plans')]);}catch(e){message.value=e.message;}}
async function save(){if(saving.value || workout?.state!=='finished')return;saving.value=true;try{await api('/api/workouts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(workout.snapshot())});savedId.value=workout.id;message.value='训练已保存；重试不会重复创建。';await load();}catch(e){message.value=e.message+'，进度仍保留，可重试。';}finally{saving.value=false;}}
function reset(){if(workout&&!savedId.value&&!confirm('本次记录尚未保存。确认放弃这条临时记录并编排下一次训练？'))return;workout=null;state.value='idle';savedId.value='';try{localStorage.removeItem(key)}catch{message.value='浏览器临时记录无法清理，请留意下次恢复提示。'}}
function selectPlan(p){if(state.value!=='idle')return;blocks.value=structuredClone(p.config?.blocks||p.blocks);name.value=p.name;description.value=p.description||'';editing.value=p.id?p:null;}
async function savePlan(){if(planBusy.value)return;planBusy.value=true;try{const body={name:name.value,description:description.value,config:{version:1,blocks:blocks.value},...(editing.value?{version:editing.value.version}:{})};const p=await api('/api/plans'+(editing.value?'/'+editing.value.id:''),{method:editing.value?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});editing.value=p;message.value='计划已保存，可在计划库中复用。';await load()}catch(e){message.value=e.message;await load()}finally{planBusy.value=false}}
async function archive(p){try{await api('/api/plans/'+p.id,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({version:p.version,archived:!p.archived})});if(editing.value?.id===p.id)editing.value=null;await load()}catch(e){message.value=e.message;await load()}}
function hidden(){if(document.hidden)pause()}
onMounted(()=>{try{const raw=JSON.parse(localStorage.getItem(key)||'null');if(raw){if(raw.savedAt>Date.now()+60000||Date.now()-raw.savedAt>86400000)throw new Error();workout=Workout.restore(raw.snapshot);blocks.value=structuredClone(workout.config.blocks);name.value=workout.planName||'我的组合训练';refresh();message.value=workout.state==='finished'?'已恢复结束的训练，可保存记录。':'已恢复暂停进度；离开时间不计入训练。';}}catch{localStorage.removeItem(key);message.value='旧流程无效或过期，请重新开始。';}load();timer=setInterval(refresh,250);document.addEventListener('visibilitychange',hidden)});
onBeforeUnmount(()=>{pause();clearInterval(timer);document.removeEventListener('visibilitychange',hidden)});
</script>
<template><section class="plan-workspace"><header><span>YOUR ROUTINE</span><h1>分组训练计划</h1><p>保存适合自己的课程组合，在同一个 3D 空间完成练习、休息与复盘。</p></header><p v-if="message" class="plan-message" role="status">{{message}}</p>
<template v-if="state==='idle'"><div class="preset-row"><button v-for="p in presets" :key="p.name" @click="selectPlan(p)"><small>训练模板</small><b>{{p.name}}</b><span>{{p.blocks.reduce((n,b)=>n+b.sets,0)}} 组 →</span></button></div><div class="plan-layout"><section class="plan-editor"><div class="plan-title"><h2>{{editing?'编辑已保存计划':'编排训练'}}</h2><span>{{preview?preview.sets+' 组 · '+(preview.seconds<60?preview.seconds+' 秒':Math.floor(preview.seconds/60)+' 分 '+(preview.seconds%60)+' 秒')+'（含休息）':'请检查参数'}}</span></div><label>计划名称<input v-model.trim="name" maxlength="60" placeholder="为这套训练取个名字"></label><label>计划说明<textarea v-model="description" maxlength="500" rows="2" placeholder="记录这套计划的安排或使用场景"></textarea></label><div v-for="(b,i) in blocks" :key="i" class="block-editor"><div><span class="block-number">{{String(i+1).padStart(2,'0')}}</span><label>课程<select v-model="b.program"><option v-for="program in programs" :key="program.id" :value="program.id">{{program.title}}</option></select></label><button v-if="blocks.length>1" @click="blocks.splice(i,1)" aria-label="移除课程段">移除</button></div><div class="block-fields"><label>组数<input v-model.number="b.sets" type="number" min="1" max="10"></label><label>练习 / 秒<input v-model.number="b.workSeconds" type="number" min="1" max="600"></label><label>休息 / 秒<input v-model.number="b.restSeconds" type="number" min="0" max="300"></label></div></div><div class="plan-buttons"><button :disabled="blocks.length>=8" @click="blocks.push({program:'focus',sets:2,workSeconds:30,restSeconds:15})">＋ 添加课程段</button><button :disabled="planBusy" @click="savePlan">{{editing?'更新计划':'保存到计划库'}}</button><button class="primary" :disabled="!preview" @click="start">开始训练 →</button></div></section><aside class="plan-library"><div class="plan-title"><h2>我的计划库</h2><label><input v-model="showArchived" type="checkbox">显示归档</label></div><p v-if="!plans.filter(p=>showArchived||!p.archived).length">保存第一套计划，下次即可直接使用。</p><article v-for="p in plans.filter(p=>showArchived||!p.archived)" :key="p.id"><small>{{p.archived?'已归档':'可使用'}} · {{p.config.blocks.length}} 段课程</small><h3>{{p.name}}</h3><p>{{p.description||'按自己的节奏体验。'}}</p><div><button :disabled="p.archived" @click="selectPlan(p)">载入计划</button><button @click="archive(p)">{{p.archived?'恢复计划':'归档'}}</button></div></article></aside></div></template>
<div v-else class="grouped-training"><div class="phase-head"><div><span>{{state==='finished'?(summary.completed?'已完成计划':'已提前结束'):state==='paused'?'训练暂停':position.type==='rest'?'组间休息':'练习进行中'}}</span><h2>{{state==='finished'?'本次训练已结束':getProgram(position.program)?.title+' · 第 '+position.set+' 组'}}</h2></div><strong>{{Math.ceil(position.remainingMs/1000)}}<small>秒</small></strong></div><div v-if="state!=='finished'" class="grouped-scene"><FitnessScene :calibration="calibration" @calibrate="calibration=$event" :intermission="position.type==='rest' && state==='running'" :key="position.program" :session-key="String(position.index)" :interval="false" :active="state==='running'&&position.type==='work'" :program="position.program||'focus'" :remaining="Math.ceil(position.remainingMs/1000)" @hit="hit" @pause="pause" @toggle="toggle" @finish="stop" @xr="v=>{if(!v)pause()}"/><div v-if="position.type==='rest'&&state==='running'" class="rest-overlay">放松一下，准备下一组<small>休息不计入有效练习时长</small></div></div><div class="workout-summary"><div><b>{{(summary.workMs/1000).toFixed(1)}}</b><span>有效秒数</span></div><div><b>{{(summary.restMs/1000).toFixed(1)}}</b><span>休息秒数</span></div><div><b>{{summary.hits}}</b><span>目标命中</span></div></div><div class="plan-buttons"><template v-if="state!=='finished'"><button class="primary" @click="toggle">{{state==='paused'?'继续训练':'暂停训练'}}</button><button @click="stop">提前结束</button></template><template v-else><button class="primary" :disabled="saving" @click="save">{{savedId?'记录已保存 · 重试不会重复':'保存训练记录'}}</button><button @click="reset">编排下一次训练</button><RouterLink v-if="savedId" to="/records">去训练档案写复盘 →</RouterLink></template></div></div>
<details class="saved-workouts"><summary>已保存的分组训练 · {{history.length}}</summary><p v-for="r in history" :key="r.id">{{new Date(r.startedAt).toLocaleString()}} · {{(r.summary.workMs/1000).toFixed(0)}} 秒练习 · {{r.summary.completed?'完整完成':'提前结束'}} <a :href="'/api/workouts/'+r.id+'/report'">JSON 报告 ↗</a></p></details><p class="plan-scope">目标命中代表点击或控制器射线交互，不代表健身动作次数；目前未测量身体姿态、心率或热量。</p></section></template>
<style scoped>
.plan-workspace{padding:8px 0 40px;color:#d8e3f2}.plan-workspace>header>span{font-size:10px;letter-spacing:3px;color:#75b4c5}.plan-workspace h1{font-size:30px;font-weight:500;margin:12px 0}.plan-workspace header p,.plan-scope{color:#899bb6;font-size:12px;line-height:1.9}.preset-row{display:grid;grid-template-columns:repeat(3,1fr);gap:15px;margin:30px 0}.preset-row button{text-align:left;padding:18px 22px;border:1px solid #324765;background:linear-gradient(110deg,#182d48,#122137);border-radius:9px;display:grid;gap:10px}.preset-row small{color:#779ab8;font-size:10px}.preset-row b{font-size:17px;font-weight:450;color:#c9e3ed}.preset-row span{font-size:11px;color:#7dabc1}.plan-layout{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(250px,1fr);gap:30px}.plan-title{display:flex;justify-content:space-between;align-items:center;margin-bottom:22px;gap:14px}.plan-title h2{font-size:16px;font-weight:450;margin:0}.plan-title>span{color:#83a3bd;font-size:11px}label{display:block;font-size:11px;color:#9cb0ca;margin-bottom:16px}input,select,textarea{width:100%;display:block;background:#112138;border:1px solid #3b506e;border-radius:5px;color:#d9e5f5;padding:11px;font:inherit;margin-top:8px}input[type=checkbox]{width:auto;display:inline;margin:0 5px 0 0}.block-editor{border:1px solid #314461;border-radius:7px;padding:20px;margin:18px 0;background:#13253c}.block-editor>div:first-child{display:flex;align-items:center;gap:18px}.block-editor>div:first-child label{flex:1}.block-number{color:#6286a9;font-size:24px}.block-fields{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.block-fields label{margin-bottom:0}.plan-workspace button{font:inherit;font-size:11px;border:1px solid #425b7b;background:#20364f;color:#abc6df;padding:10px 14px;border-radius:5px;cursor:pointer}.plan-workspace button.primary{background:#bce7ed;color:#10354a;border-color:#bce7ed}.plan-workspace button:disabled{opacity:.45;cursor:default}.plan-buttons{display:flex;gap:10px;flex-wrap:wrap;margin:20px 0;align-items:center}.plan-buttons a{font-size:12px;color:#9fd6e1}.plan-library{border-left:1px solid #2e4361;padding-left:26px}.plan-library label{margin:0;white-space:nowrap;font-size:10px}.plan-library article{border-top:1px solid #304663;padding:20px 0}.plan-library article small{font-size:10px;color:#789dbb}.plan-library article h3{font-size:17px;font-weight:450;margin:10px 0}.plan-library p{font-size:12px;color:#849eb9;line-height:1.8}.plan-library article>div{display:flex;gap:8px;margin-top:14px}.plan-message{padding:13px 16px;border-left:2px solid #79b9c8;background:#193246;color:#a8d4de;font-size:12px}.phase-head{display:flex;align-items:center;justify-content:space-between;padding:22px 0}.phase-head span{font-size:11px;color:#86afc5}.phase-head h2{font-weight:400;font-size:24px}.phase-head strong{font-size:44px;font-weight:400;color:#b9e9f1}.phase-head strong small{font-size:12px;margin-left:9px}.grouped-scene{height:440px;position:relative;border:1px solid #354f6c;border-radius:10px;overflow:hidden}.grouped-scene :deep(.fitness-scene){height:100%;min-height:0}.rest-overlay{position:absolute;bottom:60px;left:0;right:0;text-align:center;color:#bcdeed;pointer-events:none}.rest-overlay small{display:block;font-size:11px;margin-top:9px}.workout-summary{display:flex;border-bottom:1px solid #2d4360;padding:24px 0;gap:55px}.workout-summary b{font-size:26px;font-weight:400;display:block}.workout-summary span{font-size:11px;color:#819cba;display:block;margin-top:8px}.saved-workouts{border-top:1px solid #2d4360;margin-top:32px;padding:20px 0;color:#8ca8c3;font-size:12px}.saved-workouts summary{cursor:pointer}.saved-workouts p{line-height:1.9}.saved-workouts a{color:#a2cedc;margin-left:12px}.plan-scope{font-size:11px}@media(max-width:750px){.plan-workspace h1{font-size:25px}.plan-layout{grid-template-columns:1fr}.plan-library{border:0;padding:0}.preset-row{gap:8px}.preset-row button{padding:15px 12px}.preset-row b{font-size:14px}.block-editor{padding:16px}.block-fields{gap:10px}.grouped-scene{height:350px}.workout-summary{gap:35px}.plan-title{flex-wrap:wrap}}
.plan-workspace>header{display:block;position:static;height:auto;padding:0;background:transparent;border:0}
</style>
